// ---- saved choices (theme / variant): survive a restart and reach the always-on screen ----
const dcGet = (k) => {
  try { const v = Number(zosFs.readFileSync({ path: 'dc_' + k + '.txt', options: { encoding: 'utf8' } })); if (v) return v } catch (e) {}
  try { if (typeof hmFS !== 'undefined') return Number(hmFS.SysProGetInt(k)) || 0 } catch (e) {}
  return 0
}
const dcSet = (k, v) => {
  try { zosFs.writeFileSync({ path: 'dc_' + k + '.txt', data: String(v), options: { encoding: 'utf8' } }) } catch (e) {}
  try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt(k, v) } catch (e) {}
}

WatchFace({
  initView() {
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    variantIdx = dcGet('dialcraft_variant')

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Scene (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: A('scene_knit.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Minute Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(210),
      minute_startY: px(59),
      minute_zero: 1,
      minute_space: px(2),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Main_g36v,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Colon Main (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(180),
      y: px(63),
      src: A('knit/colon.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Hour Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(18),
      hour_startY: px(59),
      hour_zero: 1,
      hour_space: px(2),
      hour_align: ui.align.LEFT,
      hour_array: img_Minute_Main_g36v,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(211),
      minute_startY: px(186),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_4u9x,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Colon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(181),
      y: px(196),
      src: A('symbol_u003a_2.png'),
      show_level: ui.show_level.ONLY_AOD
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(39),
      hour_startY: px(186),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_u1yj,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(118),
      y: px(18),
      week_en: img_Weekday_02ru,
      week_sc: img_Weekday_02ru,
      week_tc: img_Weekday_02ru,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(204),
      day_startY: px(26),
      day_zero: 0,
      day_space: px(0),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_r45f,
      day_sc_array: img_Day_r45f,
      day_tc_array: img_Day_r45f,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Steps icon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(118),
      y: px(188),
      src: A('ic_steps_e2563f.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Steps (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(156),
      y: px(186),
      type: ui.data_type.STEP,
      font_array: img_Steps_15qv,
      h_space: px(1),
      align_h: ui.align.LEFT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Heart rate icon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(68),
      y: px(246),
      src: A('ic_heart_e2563f.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Heart rate (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(106),
      y: px(244),
      type: ui.data_type.HEART,
      font_array: img_Heart_rate_g5kb,
      h_space: px(1),
      align_h: ui.align.LEFT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Battery level (IMG_LEVEL)
    ui.createWidget(ui.widget.IMG_LEVEL, {
      x: px(207),
      y: px(249),
      image_array: img_Battery_level_n1bd,
      image_length: img_Battery_level_n1bd.length,
      type: ui.data_type.BATTERY,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Battery (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(255),
      y: px(244),
      type: ui.data_type.BATTERY,
      font_array: img_Battery_f3xw,
      h_space: px(1),
      align_h: ui.align.LEFT,
      unit_en: A('percent.png'),
      unit_sc: A('percent.png'),
      unit_tc: A('percent.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Ball of yarn (IMG)
    const variants_0 = [A('sp/ball_001.png'), A('sp/ball_000.png'), A('sp/ball_002.png'), A('sp/ball_003.png'), A('sp/ball_004.png'), A('sp/ball_005.png'), A('sp/ball_006.png'), A('sp/ball_007.png'), A('sp/ball_008.png')]
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(32),
      y: px(372),
      src: variants_0[variantIdx % variants_0.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.ball = variant_0
    F.ball = variants_0

    // Needles (IMG)
    const variants_1 = [A('sp/needles_010.png'), A('sp/needles_009.png'), A('sp/needles_011.png')]
    const variant_1 = ui.createWidget(ui.widget.IMG, {
      x: px(232),
      y: px(292),
      src: variants_1[variantIdx % variants_1.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.needles = variant_1
    F.needles = variants_1

    // Scarf (IMG)
    const variants_2 = [A('sp/swatch_012.png'), A('sp/swatch_013.png')]
    const variant_2 = ui.createWidget(ui.widget.IMG, {
      x: px(248),
      y: px(322),
      w: px(44),
      h: px(48),
      src: variants_2[variantIdx % variants_2.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.swatch = variant_2
    F.swatch = variants_2

    // a Tap zone set to "Cycle variants" calls this
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length, variants_1.length, variants_2.length)
      dcSet('dialcraft_variant', variantIdx)
      variant_0.setProperty(ui.prop.SRC, variants_0[variantIdx % variants_0.length])
      variant_1.setProperty(ui.prop.SRC, variants_1[variantIdx % variants_1.length])
      variant_2.setProperty(ui.prop.SRC, variants_2[variantIdx % variants_2.length])
    }

    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    {
      // Knitted Time: the needles click, the ball of yarn rocks, and one minute of scarf grows from the needles (it restarts every minute)
      const MS = 130;
      const V = {"ball":{"f1":0,"f0":1,"f2":2,"f3":3,"f4":4,"f5":5,"f6":6,"f7":7,"__blank":8},"needles":{"b":0,"a":1,"__blank":2},"swatch":{"s":0,"__blank":1}};
      const tick = () => {
        const now = Date.now(), sec = (now % 60000) / 1000;
        slot('ball')(34 + Math.round(2 * Math.sin(now / 650)), 372, V.ball['f' + (Math.floor(now / 260) % 8)]);
        slot('needles')(232, 292, Math.floor(now / 500) % 2 ? V.needles.a : V.needles.b);
        const h = Math.round(80 * sec / 60);
        if (h >= 3) slot('swatch')(248, 322, V.swatch.s, 44, h); else slot('swatch').hide();
      };
        // ---- shared runtime: slot setter that skips unchanged calls, and a loop that runs only while the face is on screen ----
      const SL = {};
      const slot = (h) => {
        if (SL[h]) return SL[h];
        const w = W[h], f = F[h]; let key = '';
        const s = (x, y, i, ww, hh) => {
          const k = x + '|' + y + '|' + i + '|' + ww + '|' + hh;
          if (k === key) return;
          key = k;
          const p = { x: pxv(x), y: pxv(y) };
          if (i !== undefined) p.src = f[i];
          if (ww !== undefined) { p.w = pxv(ww); p.h = pxv(hh); }
          w.setProperty(ui.prop.MORE, p);
        };
        s.hide = () => { if (key === 'hide') return; key = 'hide'; w.setProperty(ui.prop.MORE, { src: f[V[h].__blank] }); };
        return (SL[h] = s);
      };
      let gen = 0, running = false;
      const safe = () => { try { tick(); } catch (e) { /* a bad frame must not stop the loop */ } };
      const loop = (g) => {
        if (!running || g !== gen) return;
        safe();
        if (running && g === gen) { try { setTimeout(() => loop(g), MS); } catch (e) {} }
      };
      const start = () => {
        gen++; running = true; const g = gen;
        try { setTimeout(() => loop(g), MS); } catch (e) {}
        safe();
      };
      const stop = () => { running = false; gen++; };
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop });
      start();

    }
  },

  build() {
    this.initView()
  },
})
